#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Slime Rancher Telegram Bot — SINGLE FILE (PythonAnywhere WSGI + webhook)
Все картинки встроены через base64.
База данных (data.db) создаётся автоматически.

Установка:
  pip install pyTelegramBotAPI flask pillow

Переменные окружения:
  BOT_TOKEN       — токен бота от @BotFather (обязательно)
  WEBHOOK_URL     — публичный HTTPS-адрес приложения, например
                    https://ВАШ_ЛОГИН.pythonanywhere.com
  WEBHOOK_SECRET  — любая строка для защиты вебхука (необязательно)
  DB_PATH         — постоянный путь к data.db, например
                    /home/ВАШ_ЛОГИН/slimebot/data.db
  PORT            — порт (хостинг обычно задаёт сам)

Запуск:
  PythonAnywhere WSGI: from botik import app as application
  Локально: python botik.py
"""

import os
import re
import json
import time
import random
import sqlite3
import base64
import hashlib
import io
import sys
try:
    from PIL import Image, ImageDraw, ImageFont, ImageFilter
except ImportError:
    Image = ImageDraw = ImageFont = ImageFilter = None  # type: ignore
import traceback
import threading
from contextlib import contextmanager

try:
    import telebot
    from telebot import apihelper
    from flask import Flask, request, abort
except ImportError:
    print("Установите: pip install pyTelegramBotAPI flask")
    raise SystemExit(1)

# Повторяем временные сетевые ошибки Telegram API (например ProxyError/503).
# Это не повторяет весь webhook и не запускает обработчики повторно.
apihelper.RETRY_ON_ERROR = True
apihelper.MAX_RETRIES = 4

BOT_TOKEN = os.environ.get("BOT_TOKEN", "").strip()
if not BOT_TOKEN:
    # WSGI должен показать понятную ошибку конфигурации в error log,
    # а не завершать весь процесс через SystemExit.
    raise RuntimeError("Не задан BOT_TOKEN. Укажите его в WSGI-конфигурации PythonAnywhere.")
BASE_DIR  = os.path.dirname(os.path.abspath(__file__))

COOLDOWN_SECONDS = 10 * 60 * 60   # 10 часов
DB_FILE          = os.environ.get("DB_PATH") or os.path.join(BASE_DIR, "data.db")
CASE_COST        = 150

# Рофельная лимитка «Газява-слайм»: доступна для выпадения только 72 часа
# с момента первого запуска этой версии бота. Время хранится в bot_meta,
# поэтому перезапуск/перезагрузка WSGI не сбрасывает таймер.
GAZYAVA_EVENT_DURATION = 72 * 60 * 60
GAZYAVA_EVENT_META_KEY = "gazyava_event_started_at"

# Грядки: цена первой, множитель для каждой следующей, максимум, период урожая
GROUND_BASE_PRICE = 500
GROUND_PRICE_MULT = 1.5
GROUND_MAX        = 3
GROUND_PERIOD     = 6 * 60 * 60   # 6 часов
ADMIN_ID         = 8483781314  # /setmoney, /setslime, /setmsg

# Для одноразовой миграции со старого формата (если файлы лежат рядом)
OLD_COOLDOWNS_FILE   = os.path.join(BASE_DIR, "cooldowns.json")
OLD_COLLECTIONS_FILE = os.path.join(BASE_DIR, "collections.json")

# threaded=False: апдейт обрабатывается прямо внутри запроса вебхука.
# На PythonAnywhere (WSGI) фоновые потоки могут обрываться, так надёжнее.
bot = telebot.TeleBot(BOT_TOKEN, threaded=False)

