# ---------- Экранирование MarkdownV2 ----------
def esc(text) -> str:
    special = r"_*[]()~`>#+-=|{}.!"
    return "".join("\\" + c if c in special else c for c in str(text))


def safe_reply(message, text: str, parse_mode: str = "MarkdownV2"):
    """reply_to с запасным вариантом: если Telegram не принял разметку
    (например, где-то остался неэкранированный символ), то же сообщение
    уходит без форматирования — игрок не остаётся без ответа."""
    try:
        return bot.reply_to(message, text, parse_mode=parse_mode)
    except Exception as e:
        print(f"[reply] разметка отклонена ({type(e).__name__}) — шлю без форматирования",
              flush=True)
        plain = re.sub(r"\\(.)", r"\1", text).replace("*", "")
        return bot.reply_to(message, plain)


# ---------- SQLite ----------
@contextmanager
def db():
    # WAL + busy_timeout помогают при нескольких одновременных webhook-запросах.
    conn = sqlite3.connect(DB_FILE, timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout = 30000")
    try:
        yield conn
        conn.commit()
    finally:
        conn.close()


def init_db() -> None:
    # На PythonAnywhere база должна лежать в постоянной домашней папке,
    # а не во временной директории приложения.
    db_dir = os.path.dirname(os.path.abspath(DB_FILE))
    os.makedirs(db_dir, exist_ok=True)
    with db() as conn:
        conn.execute("PRAGMA journal_mode = WAL")
        conn.execute("PRAGMA synchronous = NORMAL")
        conn.executescript("""
        CREATE TABLE IF NOT EXISTS users (
            user_id     INTEGER PRIMARY KEY,
            username    TEXT,
            first_name  TEXT,
            updated_at  REAL,
            new_bucks   INTEGER NOT NULL DEFAULT 0,
            last_passive REAL NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS collections (
            user_id     INTEGER NOT NULL,
            slime_key   TEXT    NOT NULL,
            count       INTEGER NOT NULL DEFAULT 1,
            PRIMARY KEY (user_id, slime_key)
        );
        CREATE TABLE IF NOT EXISTS cooldowns (
            user_id     INTEGER PRIMARY KEY,
            last_used   REAL    NOT NULL
        );
        CREATE TABLE IF NOT EXISTS secret_styles (
            user_id     INTEGER NOT NULL,
            slime_key   TEXT    NOT NULL,
            unlocked_at REAL    NOT NULL,
            PRIMARY KEY (user_id, slime_key)
        );
        CREATE TABLE IF NOT EXISTS slime_instances (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id         INTEGER NOT NULL,
            slime_key       TEXT NOT NULL,
            acquired_at     REAL NOT NULL,
            last_fed_at     REAL NOT NULL,
            wild_since      REAL,
            wild_attack_done INTEGER NOT NULL DEFAULT 0,
            last_feed_action_at REAL NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS food_meta (
            key   TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS food_inventory (
            user_id INTEGER NOT NULL,
            food_id TEXT NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (user_id, food_id)
        );
        CREATE TABLE IF NOT EXISTS plort_inventory (
            user_id INTEGER NOT NULL, slime_key TEXT NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (user_id, slime_key)
        );
        CREATE TABLE IF NOT EXISTS plort_market (
            hour_slot INTEGER NOT NULL, slime_key TEXT NOT NULL,
            price INTEGER NOT NULL, delta_pct INTEGER NOT NULL,
            PRIMARY KEY (hour_slot, slime_key)
        );
        CREATE TABLE IF NOT EXISTS grounds (
            user_id      INTEGER NOT NULL,
            slot         INTEGER NOT NULL,
            price        INTEGER NOT NULL,
            food_id      TEXT,
            last_harvest REAL,
            PRIMARY KEY (user_id, slot)
        );
        CREATE TABLE IF NOT EXISTS chats (
            chat_id    INTEGER PRIMARY KEY,
            chat_type  TEXT,
            title      TEXT,
            updated_at REAL
        );
        CREATE TABLE IF NOT EXISTS role_members (
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            name TEXT NOT NULL DEFAULT '',
            custom_title TEXT NOT NULL DEFAULT '',
            last_seen REAL NOT NULL DEFAULT 0,
            PRIMARY KEY (chat_id, user_id)
        );
        CREATE TABLE IF NOT EXISTS bot_meta (
            key   TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS quests (
            user_id      INTEGER PRIMARY KEY,
            quest_key    TEXT NOT NULL,
            quest_title  TEXT NOT NULL,
            difficulty   TEXT NOT NULL,
            target       INTEGER NOT NULL,
            progress     INTEGER NOT NULL DEFAULT 0,
            reward_base  INTEGER NOT NULL,
            created_at   REAL NOT NULL,
            claimed      INTEGER NOT NULL DEFAULT 0
        );
        CREATE INDEX IF NOT EXISTS idx_quests_user ON quests(user_id);
        CREATE TABLE IF NOT EXISTS promo_codes (
            code       TEXT PRIMARY KEY,
            max_uses   INTEGER NOT NULL,
            uses       INTEGER NOT NULL DEFAULT 0,
            reward     INTEGER NOT NULL,
            created_at REAL NOT NULL
        );
        CREATE TABLE IF NOT EXISTS promo_activations (
            code         TEXT NOT NULL,
            user_id      INTEGER NOT NULL,
            activated_at REAL NOT NULL,
            PRIMARY KEY (code, user_id),
            FOREIGN KEY (code) REFERENCES promo_codes(code)
        );
        CREATE INDEX IF NOT EXISTS idx_promo_activations_user
            ON promo_activations(user_id);
        CREATE INDEX IF NOT EXISTS idx_collections_user
            ON collections(user_id);
        CREATE INDEX IF NOT EXISTS idx_styles_user
            ON secret_styles(user_id);
        CREATE INDEX IF NOT EXISTS idx_slime_instances_user
            ON slime_instances(user_id, slime_key);
        """)
        # Миграция: добавить колонки если старая БД
        try:
            conn.execute("ALTER TABLE users ADD COLUMN new_bucks INTEGER NOT NULL DEFAULT 0")
        except sqlite3.OperationalError:
            pass
        try:
            conn.execute("ALTER TABLE users ADD COLUMN last_passive REAL NOT NULL DEFAULT 0")
        except sqlite3.OperationalError:
            pass
        try:
            conn.execute("ALTER TABLE slime_instances ADD COLUMN last_feed_action_at REAL NOT NULL DEFAULT 0")
        except sqlite3.OperationalError:
            pass
        # Один раз переносим уже известных игроков в список чатов для /setmsg.
        # Группы старого времени добавятся сами, когда в них кто-то напишет боту.
        if not conn.execute("SELECT 1 FROM bot_meta WHERE key='chats_seeded'").fetchone():
            conn.execute(
                """INSERT OR IGNORE INTO chats(chat_id, chat_type, title, updated_at)
                   SELECT user_id, 'private', NULL, 0 FROM users"""
            )
            conn.execute("INSERT OR REPLACE INTO bot_meta(key, value) VALUES('chats_seeded', '1')")
        # Миграция цен плортов: старые цены были слишком высокими для обычных слаймов.
        # Пересчитываем рынок один раз, чтобы новые цены действовали сразу.
        plort_price_version = conn.execute(
            "SELECT value FROM bot_meta WHERE key='plort_price_version'"
        ).fetchone()
        if not plort_price_version or plort_price_version[0] != '2':
            conn.execute("DELETE FROM plort_market")
            conn.execute(
                "INSERT OR REPLACE INTO bot_meta(key, value) VALUES('plort_price_version', '2')"
            )


def ensure_gazyava_event_start() -> float:
    """Создаёт неизменяемое время старта 72-часового события."""
    now = time.time()
    with db() as conn:
        row = conn.execute("SELECT value FROM bot_meta WHERE key=?", (GAZYAVA_EVENT_META_KEY,)).fetchone()
        if row:
            try:
                return float(row["value"])
            except (TypeError, ValueError):
                pass
        conn.execute("INSERT OR REPLACE INTO bot_meta(key, value) VALUES(?, ?)", (GAZYAVA_EVENT_META_KEY, str(now)))
        return now

def get_gazyava_event_start() -> float:
    with db() as conn:
        row = conn.execute("SELECT value FROM bot_meta WHERE key=?", (GAZYAVA_EVENT_META_KEY,)).fetchone()
        if row:
            try:
                return float(row["value"])
            except (TypeError, ValueError):
                pass
    return ensure_gazyava_event_start()

def gazyava_event_remaining(now: float | None = None) -> float:
    now = time.time() if now is None else now
    return max(0.0, GAZYAVA_EVENT_DURATION - (now - get_gazyava_event_start()))

def gazyava_event_active(now: float | None = None) -> bool:
    return gazyava_event_remaining(now) > 0

def touch_user(user) -> None:
    """Обновляет/создаёт запись пользователя."""
    with db() as conn:
        conn.execute(
            """INSERT INTO users(user_id, username, first_name, updated_at, new_bucks, last_passive)
               VALUES(?, ?, ?, ?, 0, ?)
               ON CONFLICT(user_id) DO UPDATE SET
                   username   = excluded.username,
                   first_name = excluded.first_name,
                   updated_at = excluded.updated_at""",
            (user.id, user.username, user.first_name, time.time(), time.time()),
        )

    # Проверяем состояние питомцев при любой команде пользователя.
    # В WSGI нельзя полагаться на постоянно работающий фоновый поток.
    try:
        events = process_hunger(user.id, load_slimes())
        for event in events:
            try:
                bot.send_message(user.id, event)
            except Exception:
                pass
    except Exception as e:
        print(f"[food] ошибка обновления голода: {type(e).__name__}")

    # Урожай с грядок начисляется «лениво»: при любой команде игрока.
    try:
        collect_garden(user.id)
    except Exception as e:
        print(f"[garden] ошибка сбора урожая: {type(e).__name__}")


# ---------- Чаты и рассылка (/setmsg) ----------
BROADCAST_TIME_BUDGET = 45   # секунд на рассылку внутри одного запроса вебхука


def record_chat(chat) -> None:
    """Запоминает чат (ЛС или группу), из которого бот получил апдейт."""
    try:
        title = getattr(chat, "title", None) or getattr(chat, "first_name", None) or ""
        with db() as conn:
            conn.execute(
                """INSERT INTO chats(chat_id, chat_type, title, updated_at)
                   VALUES(?, ?, ?, ?)
                   ON CONFLICT(chat_id) DO UPDATE SET
                       chat_type  = excluded.chat_type,
                       title      = excluded.title,
                       updated_at = excluded.updated_at""",
                (int(chat.id), getattr(chat, "type", "") or "", title, time.time()),
            )
    except Exception as e:
        print(f"[chats] не удалось записать чат: {type(e).__name__}", flush=True)


def _tg_error_info(e):
    code = getattr(e, "error_code", None)
    desc = str(getattr(e, "description", "") or e).lower()
    try:
        params = (getattr(e, "result_json", None) or {}).get("parameters") or {}
    except Exception:
        params = {}
    return code, desc, params


def broadcast_text(text: str) -> dict:
    """Шлёт text (обычным текстом, без разметки) во все известные чаты."""
    with db() as conn:
        rows = conn.execute("SELECT chat_id, chat_type FROM chats").fetchall()
    stats = {"total": len(rows), "sent": 0, "private": 0, "groups": 0,
             "failed": 0, "removed": 0, "skipped": 0}
    started = time.time()

    for i, row in enumerate(rows):
        if time.time() - started > BROADCAST_TIME_BUDGET:
            stats["skipped"] = len(rows) - i
            break
        chat_id = row["chat_id"]
        is_private = (row["chat_type"] == "private")

        for attempt in range(2):
            try:
                bot.send_message(chat_id, text)
                stats["sent"] += 1
                stats["private" if is_private else "groups"] += 1
                break
            except Exception as e:
                code, desc, params = _tg_error_info(e)
                if code == 429 and attempt == 0:
                    time.sleep(min(int(params.get("retry_after", 3)), 10) + 1)
                    continue
                new_id = params.get("migrate_to_chat_id")
                if new_id and attempt == 0:
                    # группа стала супергруппой — переносим запись и пробуем ещё раз
                    with db() as conn:
                        conn.execute("DELETE FROM chats WHERE chat_id=?", (chat_id,))
                        conn.execute(
                            """INSERT OR IGNORE INTO chats(chat_id, chat_type, title, updated_at)
                               VALUES(?, 'supergroup', '', ?)""",
                            (int(new_id), time.time()),
                        )
                    chat_id = int(new_id)
                    continue
                stats["failed"] += 1
                # бота выгнали / ЛС заблокировали / чата больше нет — убираем из списка
                if code == 403 or (code == 400 and "chat not found" in desc):
                    with db() as conn:
                        conn.execute("DELETE FROM chats WHERE chat_id=?", (chat_id,))
                    stats["removed"] += 1
                else:
                    print(f"[broadcast] {chat_id}: {code} {desc[:80]}", flush=True)
                break
        time.sleep(0.05)   # ~20 сообщений/сек, в пределах лимитов Telegram
    return stats


def migrate_from_json() -> None:
    """Один раз подхватывает старые cooldowns.json / collections.json."""
    if os.path.exists(OLD_COOLDOWNS_FILE):
        try:
            with open(OLD_COOLDOWNS_FILE, "r", encoding="utf-8") as f:
                old = json.load(f)
            with db() as conn:
                for uid, ts in old.items():
                    conn.execute(
                        """INSERT INTO cooldowns(user_id, last_used)
                           VALUES(?, ?)
                           ON CONFLICT(user_id) DO UPDATE SET
                               last_used = MAX(cooldowns.last_used,
                                               excluded.last_used)""",
                        (int(uid), float(ts)),
                    )
            os.rename(OLD_COOLDOWNS_FILE, OLD_COOLDOWNS_FILE + ".migrated")
            print(f"[migrate] cooldowns.json → {len(old)} записей")
        except Exception as e:
            print(f"[migrate] cooldowns: {e}")

    if os.path.exists(OLD_COLLECTIONS_FILE):
        try:
            with open(OLD_COLLECTIONS_FILE, "r", encoding="utf-8") as f:
                old = json.load(f)
            n = 0
            with db() as conn:
                for uid, items in old.items():
                    for key, count in items.items():
                        conn.execute(
                            """INSERT INTO collections(user_id, slime_key, count)
                               VALUES(?, ?, ?)
                               ON CONFLICT(user_id, slime_key) DO UPDATE SET
                                   count = collections.count + excluded.count""",
                            (int(uid), key, int(count)),
                        )
                        n += 1
            os.rename(OLD_COLLECTIONS_FILE,
                      OLD_COLLECTIONS_FILE + ".migrated")
            print(f"[migrate] collections.json → {n} записей")
        except Exception as e:
            print(f"[migrate] collections: {e}")


# ---------- Валюта и пассив ----------
def get_bucks(user_id: int) -> int:
    with db() as conn:
        row = conn.execute(
            "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
        ).fetchone()
        return int(row["new_bucks"]) if row else 0


def find_user_by_username(username: str):
    """Ищет user_id по username (без @) или по числовому id.
    Возвращает (user_id, display_name) или None."""
    raw = username.lstrip("@").strip()
    if not raw:
        return None

    # Сначала пробуем как user_id
    if raw.isdigit():
        uid = int(raw)
        with db() as conn:
            row = conn.execute(
                "SELECT user_id, first_name, username FROM users WHERE user_id=?",
                (uid,),
            ).fetchone()
            if row:
                name = row["first_name"] or row["username"] or str(uid)
                return int(row["user_id"]), name
            # Даже если нет в users — разрешаем по id (для админ-команд)
            return uid, str(uid)

    uname = raw.lower()
    with db() as conn:
        row = conn.execute(
            "SELECT user_id, first_name, username FROM users WHERE lower(username)=?",
            (uname,),
        ).fetchone()
        if row:
            return int(row["user_id"]), row["first_name"] or row["username"] or uname
    return None


def set_bucks_absolute(user_id: int, amount: int) -> int:
    """Жёстко ставит баланс = amount. Возвращает новый баланс."""
    amount = max(0, int(amount))
    with db() as conn:
        conn.execute(
            """INSERT INTO users(user_id, new_bucks, last_passive, updated_at)
               VALUES(?, ?, ?, ?)
               ON CONFLICT(user_id) DO UPDATE SET
                   new_bucks = excluded.new_bucks,
                   updated_at = excluded.updated_at""",
            (user_id, amount, time.time(), time.time()),
        )
        row = conn.execute(
            "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
        ).fetchone()
        return int(row["new_bucks"]) if row else amount


def add_bucks(user_id: int, amount: int) -> int:
    """Добавляет (или отнимает) баксы. Возвращает новый баланс."""
    with db() as conn:
        conn.execute(
            """INSERT INTO users(user_id, new_bucks, last_passive, updated_at)
               VALUES(?, ?, ?, ?)
               ON CONFLICT(user_id) DO UPDATE SET
                   new_bucks = MAX(0, users.new_bucks + excluded.new_bucks)""",
            (user_id, amount, time.time(), time.time()),
        )
        row = conn.execute(
            "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
        ).fetchone()
        return int(row["new_bucks"]) if row else 0


def get_food_price(food_item: dict, now: float | None = None) -> int:
    """Цена меняется раз в час; любимая еда заметно дороже."""
    now = time.time() if now is None else now
    hour_slot = int(now // 3600)
    food_id = str(food_item.get("id", "food"))
    favorite = bool(food_item.get("favorite_of"))
    base = 120 if favorite else 55
    # Небольшой дополнительный коэффициент для особой еды.
    if food_id in {"gilded_ginger", "kookadoba"}:
        base = 180 if favorite else 85
    phase = (hour_slot + sum(ord(ch) for ch in food_id)) % 9
    multiplier = 0.80 + phase * 0.05
    return max(1, round(base * multiplier))


def get_food_quantity(user_id: int, food_id: str) -> int:
    with db() as conn:
        row = conn.execute(
            "SELECT quantity FROM food_inventory WHERE user_id=? AND food_id=?",
            (user_id, food_id),
        ).fetchone()
        return int(row["quantity"]) if row else 0


def buy_food(user_id: int, food_id: str, quantity: int = 1) -> tuple[bool, str]:
    item = next((x for x in FOOD_ITEMS if x.get("id") == food_id and x.get("edible_by_slimes")), None)
    if not item:
        return False, "Такой еды нет в магазине."
    if quantity < 1 or quantity > 99:
        return False, "Можно купить от 1 до 99 штук за раз."
    price = get_food_price(item)
    total = price * quantity
    with db() as conn:
        # Списываем одним запросом с проверкой баланса: двойной клик не уведёт в минус.
        cur = conn.execute(
            "UPDATE users SET new_bucks=new_bucks-? WHERE user_id=? AND new_bucks>=?",
            (total, user_id, total),
        )
        if cur.rowcount == 0:
            row = conn.execute(
                "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
            ).fetchone()
            balance = int(row["new_bucks"]) if row else 0
            return False, f"Недостаточно Newbucks. Нужно {total} 💵, у вас {balance} 💵."
        # UPDATE → INSERT вместо ON CONFLICT: работает даже если в старой БД
        # у food_inventory нет PRIMARY KEY (иначе покупка падала бы с ошибкой).
        cur = conn.execute(
            "UPDATE food_inventory SET quantity=quantity+? WHERE user_id=? AND food_id=?",
            (quantity, user_id, food_id),
        )
        if cur.rowcount == 0:
            conn.execute(
                "INSERT INTO food_inventory(user_id, food_id, quantity) VALUES(?, ?, ?)",
                (user_id, food_id, quantity),
            )
        row = conn.execute(
            "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
        ).fetchone()
        new_balance = int(row["new_bucks"]) if row else 0
    return True, f"Куплено: {item['name']} ×{quantity}. Потрачено {total} 💵. Остаток: {new_balance} 💵."


def consume_food(user_id: int, food_id: str) -> bool:
    with db() as conn:
        row = conn.execute(
            "SELECT quantity FROM food_inventory WHERE user_id=? AND food_id=?",
            (user_id, food_id),
        ).fetchone()
        if not row or int(row["quantity"]) < 1:
            return False
        conn.execute(
            "UPDATE food_inventory SET quantity=quantity-1 WHERE user_id=? AND food_id=?",
            (user_id, food_id),
        )
        return True


# ---------- Плорты и плорт-маркет ----------
# Цена зависит от редкости слайма, максимум — 350💵 за 1 плорт.
PLORT_MAX_PRICE = 350
PLORT_RARITY_BASE = {
    "⚪️ Начальный": 15,
    "🟠 Редкий": 30,
    "🔵 Сверх-редкий": 50,
    "🟣 Эпический": 90,
    "🟡 Легендарный": 180,
    "⚠️ Смертоносный!": 300,
    "🩷 Лимитка": 250,
}

def get_plort_price(slime_key: str, now: float | None = None) -> tuple[int, int]:
    now = time.time() if now is None else now
    hour_slot = int(now // 3600)
    slimes = load_slimes()
    rarity = slimes.get(slime_key, {}).get("rar", "⚪️ Начальный")
    base_price = PLORT_RARITY_BASE.get(rarity, 15)

    with db() as conn:
        row = conn.execute(
            "SELECT price, delta_pct FROM plort_market WHERE hour_slot=? AND slime_key=?",
            (hour_slot, slime_key),
        ).fetchone()
        if row:
            return min(int(row["price"]), PLORT_MAX_PRICE), int(row["delta_pct"])

        # Небольшое почасовое колебание, но жёсткий потолок 350💵.
        rng = random.Random(f"plort:v2:{hour_slot}:{slime_key}")
        delta_pct = rng.randint(-20, 20)
        price = max(1, min(PLORT_MAX_PRICE, round(base_price * (1 + delta_pct / 100.0))))
        conn.execute(
            "INSERT OR IGNORE INTO plort_market(hour_slot, slime_key, price, delta_pct) VALUES(?, ?, ?, ?)",
            (hour_slot, slime_key, price, delta_pct),
        )
        return price, delta_pct

def get_plort_quantity(user_id: int, slime_key: str) -> int:
    with db() as conn:
        row = conn.execute("SELECT quantity FROM plort_inventory WHERE user_id=? AND slime_key=?", (user_id, slime_key)).fetchone()
        return int(row["quantity"]) if row else 0

def add_plorts(user_id: int, slime_key: str, quantity: int) -> int:
    with db() as conn:
        cur = conn.execute("UPDATE plort_inventory SET quantity=quantity+? WHERE user_id=? AND slime_key=?", (quantity, user_id, slime_key))
        if cur.rowcount == 0:
            conn.execute("INSERT INTO plort_inventory(user_id, slime_key, quantity) VALUES(?, ?, ?)", (user_id, slime_key, quantity))
        row = conn.execute("SELECT quantity FROM plort_inventory WHERE user_id=? AND slime_key=?", (user_id, slime_key)).fetchone()
        return int(row["quantity"]) if row else quantity

def sell_plorts(user_id: int, slime_key: str, quantity: int) -> tuple[bool, str]:
    if quantity < 1:
        return False, "Количество должно быть минимум 1."
    slimes = load_slimes()
    if slime_key not in slimes or slime_key == "tarr_slime":
        return False, "Такого плорта нет."
    price, _ = get_plort_price(slime_key)
    with db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute("SELECT quantity FROM plort_inventory WHERE user_id=? AND slime_key=?", (user_id, slime_key)).fetchone()
        owned = int(row["quantity"]) if row else 0
        if owned < quantity:
            return False, f"У вас только {owned} плорт(ов) этого слайма."
        cur = conn.execute("UPDATE plort_inventory SET quantity=quantity-? WHERE user_id=? AND slime_key=? AND quantity>=?", (quantity, user_id, slime_key, quantity))
        if cur.rowcount != 1:
            return False, "Не удалось продать плорты. Попробуйте ещё раз."
        total = price * quantity
        conn.execute("UPDATE users SET new_bucks=new_bucks+? WHERE user_id=?", (total, user_id))
        row = conn.execute("SELECT new_bucks FROM users WHERE user_id=?", (user_id,)).fetchone()
        balance = int(row["new_bucks"]) if row else 0
    return True, f"Продано: {slimes[slime_key].get('Name', slime_key)} ×{quantity}. Получено {total} 💵 ({price} 💵/шт.). Баланс: {balance} 💵."

def send_plort_market(chat_id: int, user_id: int) -> None:
    slimes = load_slimes()
    left = 3600 - (int(time.time()) % 3600)
    minutes, seconds = divmod(left, 60)
    rows = []
    for slime_key in slimes:
        if slime_key == "tarr_slime": continue
        price, delta = get_plort_price(slime_key)
        arrow = "📈" if delta > 0 else ("📉" if delta < 0 else "➖")
        sign = "+" if delta > 0 else ""
        owned = get_plort_quantity(user_id, slime_key)
        name = re.sub(r"слайм", "плорт", slimes[slime_key].get("Name", slime_key), flags=re.I)
        rows.append(f"• {name} — *{price}* 💵 {arrow} {sign}{delta}%  _(у вас: {owned})_")
    text = ("💎 *Плорт-маркет*\nЦена зависит от редкости слайма, максимум — *350* 💵 за 1 плорт. Каждый час цена меняется на ±20%.\n\n" + "\n".join(rows) + f"\n\n⏳ Следующее изменение цен через *{minutes} мин. {seconds} сек.*\n\nПродать: `/plort золотой` или `сдать золотой`\nНесколько: `/plort золотой 3`")
    bot.send_message(chat_id, text, parse_mode="Markdown")

def is_market_trigger(message) -> bool:
    if not message.text: return False
    first = message.text.strip().lower().split(maxsplit=1)[0].split("@", 1)[0]
    return first in {"/market", "маркет", "плортмаркет", "плорт-маркет"}

@bot.message_handler(func=is_market_trigger)
def market_cmd(message):
    user = message.from_user
    touch_user(user); calc_passive_income(user.id)
    send_plort_market(message.chat.id, user.id)

def is_plort_collection_trigger(message) -> bool:
    if not message.text:
        return False
    first = message.text.strip().lower().split(maxsplit=1)[0].split("@", 1)[0]
    return first in {"/plorts", "плорты", "мои плорты", "плорт-коллекция"}

@bot.message_handler(func=is_plort_collection_trigger)
def plorts_collection_cmd(message):
    """Показывает все плорты пользователя, сгруппированные как коллекция."""
    user = message.from_user
    _prep_user(user)
    slimes = load_slimes()

    with db() as conn:
        rows = conn.execute(
            "SELECT slime_key, quantity FROM plort_inventory WHERE user_id=? AND quantity>0 ORDER BY slime_key",
            (user.id,),
        ).fetchall()

    if not rows:
        bot.reply_to(
            message,
            "💎 У вас пока нет плортов.\n"
            "Покормите слаймов, чтобы получить их! 🍽️",
        )
        return

    total = 0
    lines = []
    for row in rows:
        slime_key = row["slime_key"]
        quantity = int(row["quantity"])
        total += quantity
        name = slimes.get(slime_key, {}).get("Name", slime_key)
        plort_name = re.sub(r"\bслайм\b", "плорт", name, flags=re.I)
        lines.append(f"• {plort_name} — *{quantity}* 💎")

    text = (
        "💎 *Моя коллекция плортов*\n\n"
        + "\n".join(lines)
        + f"\n\n📦 Всего плортов: *{total}*"
        + "\n\n💵 Цены: /market"
        + "\n💰 Продажа: /plort [название]"
    )
    bot.reply_to(message, text, parse_mode="Markdown")


def is_plort_trigger(message) -> bool:
    if not message.text: return False
    first = message.text.strip().lower().split(maxsplit=1)[0].split("@", 1)[0]
    return first in {"/plort", "плорт", "сдать", "/сдать"}

@bot.message_handler(func=is_plort_trigger)
def plort_cmd(message):
    user = message.from_user; _prep_user(user)
    tokens = _args(message).split(); quantity = 1
    if tokens and tokens[-1].isdigit(): quantity = int(tokens.pop())
    query = " ".join(tokens).strip()
    if not query:
        bot.reply_to(message, "Использование: /plort золотой\nНесколько: /plort золотой 3\nЦены: /market"); return
    slimes = load_slimes()
    slime_key = find_slime_key_by_name(query, slimes)
    if not slime_key:
        slime_key = find_slime_key_by_name(re.sub(r"плорт", "", query, flags=re.I).strip(), slimes)
    if not slime_key or slime_key == "tarr_slime":
        bot.reply_to(message, "❌ Не нашёл такой плорт. Посмотреть все: /market"); return
    try: ok, result = sell_plorts(user.id, slime_key, quantity)
    except Exception:
        print("[plort] ошибка продажи:", file=sys.stderr, flush=True); traceback.print_exc(file=sys.stderr)
        ok, result = False, "Не удалось продать плорт. Попробуйте ещё раз."

    if ok:
        quest_add_progress(user.id, "sell_plort", quantity)
        plort_img = PLORT_PACK_ASSETS.get(slime_key)
        if plort_img:
            try:
                photo = get_photo_source(plort_img)
                if photo is not None:
                    bot.send_photo(
                        message.chat.id,
                        photo,
                        caption=("✅ " if ok else "❌ ") + result,
                        reply_to_message_id=message.message_id,
                    )
                    try:
                        if hasattr(photo, "close"):
                            photo.close()
                    except Exception:
                        pass
                    return
            except Exception as e:
                print(f"[plort photo] ошибка Telegram API/сети: {type(e).__name__}")

    bot.reply_to(message, ("✅ " if ok else "❌ ") + result)


