@bot.message_handler(func=is_promos_trigger)
def promos_cmd(message):
    """Показывает промокоды, у которых ещё остались активации."""
    try:
        with db() as conn:
            rows = conn.execute(
                """SELECT code, max_uses, uses, reward
                   FROM promo_codes
                   WHERE uses < max_uses
                   ORDER BY created_at DESC, code ASC"""
            ).fetchall()
    except Exception:
        print("[promos] ошибка получения списка промокодов:", file=sys.stderr, flush=True)
        traceback.print_exc(file=sys.stderr)
        safe_reply(message, "❌ Не удалось получить список промокодов. Попробуйте ещё раз.")
        return

    if not rows:
        safe_reply(message, "🎟 Сейчас нет промокодов с доступными активациями.")
        return

    lines = ["🎟 Доступные промокоды", ""]
    for row in rows:
        remaining = int(row["max_uses"]) - int(row["uses"])
        lines.append(
            f"• {row['code']} — осталось {remaining} активаций · награда {int(row['reward'])} Newbucks"
        )

    lines.append("")
    lines.append("💡 Активировать: /promo КОД")
    safe_reply(message, "\n".join(lines))


