def send_shop(chat_id: int, user_id: int):
    hour_left = 3600 - (int(time.time()) % 3600)
    minutes, seconds = divmod(hour_left, 60)
    rows = []
    for item in FOOD_ITEMS:
        if not item.get("edible_by_slimes"):
            continue
        price = get_food_price(item)
        favorite = item.get("favorite_of")
        tag = " ⭐ любимая" if favorite else ""
        stock = get_food_quantity(user_id, item["id"])
        rows.append(f"• {item['name']} — *{price}* 💵{tag}  _(у вас: {stock})_")
    balance = get_bucks(user_id)
    text = (
        "🛒 *Рынок еды для слаймов*\n"
        f"💵 Баланс: *{balance}* Newbucks\n\n"
        + "\n".join(rows)
        + f"\n\n⏳ Новые цены через *{minutes} мин. {seconds} сек.*"
        + "\n\n🛍 Купить: `/buy морковь` или `купить морковь`"
        + "\nНесколько штук: `/buy морковь 3`"
    )
    bot.send_message(chat_id, text, parse_mode="Markdown")


