# ====================== ГРЯДКИ ======================
def ground_price(owned: int) -> int:
    """Цена следующей грядки, если уже куплено owned штук: 500, 750, 1125."""
    return int(round(GROUND_BASE_PRICE * (GROUND_PRICE_MULT ** owned)))


def _food_by_id(food_id: str):
    return next((x for x in FOOD_ITEMS if x.get("id") == food_id), None)


def _food_title(food_id: str) -> str:
    item = _food_by_id(food_id)
    return item.get("name", food_id) if item else str(food_id)


def _add_food_conn(conn, user_id: int, food_id: str, quantity: int) -> None:
    """Кладёт еду в инвентарь (UPDATE → INSERT, без зависимости от ON CONFLICT)."""
    cur = conn.execute(
        "UPDATE food_inventory SET quantity=quantity+? WHERE user_id=? AND food_id=?",
        (quantity, user_id, food_id),
    )
    if cur.rowcount == 0:
        conn.execute(
            "INSERT INTO food_inventory(user_id, food_id, quantity) VALUES(?, ?, ?)",
            (user_id, food_id, quantity),
        )


def _collect_garden_conn(conn, user_id: int, now: float) -> dict:
    """Начисляет урожай за прошедшие 6-часовые циклы. Возвращает {food_id: штук}."""
    rows = conn.execute(
        "SELECT slot, food_id, last_harvest FROM grounds "
        "WHERE user_id=? AND food_id IS NOT NULL",
        (user_id,),
    ).fetchall()
    totals: dict = {}
    for r in rows:
        last = r["last_harvest"]
        if last is None:
            continue
        cycles = int((now - float(last)) // GROUND_PERIOD)
        if cycles <= 0:
            continue
        # Условие по last_harvest защищает от двойного начисления при параллельных запросах.
        cur = conn.execute(
            "UPDATE grounds SET last_harvest=? "
            "WHERE user_id=? AND slot=? AND last_harvest=?",
            (float(last) + cycles * GROUND_PERIOD, user_id, r["slot"], last),
        )
        if cur.rowcount != 1:
            continue
        _add_food_conn(conn, user_id, r["food_id"], cycles)
        totals[r["food_id"]] = totals.get(r["food_id"], 0) + cycles
    return totals


def collect_garden(user_id: int, now: float | None = None) -> dict:
    now = time.time() if now is None else now
    with db() as conn:
        has = conn.execute(
            "SELECT 1 FROM grounds WHERE user_id=? AND food_id IS NOT NULL LIMIT 1",
            (user_id,),
        ).fetchone()
        if not has:
            return {}
        return _collect_garden_conn(conn, user_id, now)


def get_grounds(user_id: int) -> list:
    with db() as conn:
        return conn.execute(
            "SELECT slot, price, food_id, last_harvest FROM grounds "
            "WHERE user_id=? ORDER BY slot",
            (user_id,),
        ).fetchall()


def buy_ground(user_id: int) -> tuple[bool, str]:
    with db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        owned = [r["slot"] for r in conn.execute(
            "SELECT slot FROM grounds WHERE user_id=? ORDER BY slot", (user_id,)
        ).fetchall()]
        if len(owned) >= GROUND_MAX:
            return False, f"У вас уже максимум грядок ({GROUND_MAX}). Посмотреть: /grounds"
        price = ground_price(len(owned))
        cur = conn.execute(
            "UPDATE users SET new_bucks=new_bucks-? WHERE user_id=? AND new_bucks>=?",
            (price, user_id, price),
        )
        if cur.rowcount == 0:
            row = conn.execute(
                "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
            ).fetchone()
            balance = int(row["new_bucks"]) if row else 0
            return False, f"Недостаточно Newbucks. Грядка стоит {price} 💵, у вас {balance} 💵."
        slot = next(i for i in range(1, GROUND_MAX + 1) if i not in owned)
        conn.execute(
            "INSERT INTO grounds(user_id, slot, price, food_id, last_harvest) "
            "VALUES(?, ?, ?, NULL, NULL)",
            (user_id, slot, price),
        )
        row = conn.execute(
            "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
        ).fetchone()
        balance = int(row["new_bucks"]) if row else 0
    text = f"🌱 Куплена грядка №{slot} за {price} 💵. Остаток: {balance} 💵.\n"
    text += f"Засадить: /newfood морковь {slot}"
    if len(owned) + 1 < GROUND_MAX:
        text += f"\nСледующая грядка: {ground_price(len(owned) + 1)} 💵 (/ground)"
    return True, text


def plant_food(user_id: int, food_id: str, slot: int) -> tuple[bool, str]:
    name = _food_title(food_id)
    with db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        g = conn.execute(
            "SELECT food_id FROM grounds WHERE user_id=? AND slot=?", (user_id, slot)
        ).fetchone()
        if not g:
            return False, f"У вас нет грядки №{slot}. Купить: /ground"
        if g["food_id"]:
            return False, (f"Грядка №{slot} уже занята: {_food_title(g['food_id'])}. "
                           f"Освободить: /rmground {slot} (грядка будет продана)")
        cur = conn.execute(
            "UPDATE food_inventory SET quantity=quantity-1 "
            "WHERE user_id=? AND food_id=? AND quantity>=1",
            (user_id, food_id),
        )
        if cur.rowcount == 0:
            return False, f"У вас нет «{name}» в запасах. Купить: /buy {name.lower()}"
        conn.execute(
            "UPDATE grounds SET food_id=?, last_harvest=? WHERE user_id=? AND slot=?",
            (food_id, time.time(), user_id, slot),
        )
    hours = GROUND_PERIOD // 3600
    return True, (f"🌿 Засажено: {name} на грядке №{slot}.\n"
                  f"Каждые {hours} ч грядка будет давать +1 шт. Смотреть: /grounds")


def remove_ground(user_id: int, slot: int) -> tuple[bool, str]:
    with db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        # Сначала добираем созревший урожай, чтобы ничего не пропало.
        _collect_garden_conn(conn, user_id, time.time())
        g = conn.execute(
            "SELECT price, food_id FROM grounds WHERE user_id=? AND slot=?",
            (user_id, slot),
        ).fetchone()
        if not g:
            return False, f"У вас нет грядки №{slot}."
        refund = int(g["price"]) // 2
        returned = g["food_id"]
        conn.execute("DELETE FROM grounds WHERE user_id=? AND slot=?", (user_id, slot))
        conn.execute(
            "UPDATE users SET new_bucks=new_bucks+? WHERE user_id=?", (refund, user_id)
        )
        if returned:
            _add_food_conn(conn, user_id, returned, 1)
        row = conn.execute(
            "SELECT new_bucks FROM users WHERE user_id=?", (user_id,)
        ).fetchone()
        balance = int(row["new_bucks"]) if row else 0
    text = f"🗑 Грядка №{slot} убрана. Возвращено: {refund} 💵"
    if returned:
        text += f" и {_food_title(returned)} ×1"
    return True, text + f". Баланс: {balance} 💵."


def _first_word(message) -> str:
    parts = (message.text or "").strip().lower().split(maxsplit=1)
    return parts[0].split("@", 1)[0] if parts else ""


def _args(message) -> str:
    parts = (message.text or "").strip().split(maxsplit=1)
    return parts[1].strip() if len(parts) > 1 else ""


def _parse_slot(token: str):
    """Номер грядки 1..GROUND_MAX или None."""
    if token.isdigit() and 1 <= int(token) <= GROUND_MAX:
        return int(token)
    return None


